func detectImageOSesOnServer(containerHost osTypeInterface) (oses []osTypeInterface) {
	containerHostInfo := containerHost.getServerInfo()
	for _, copied := range imageServerInfos(containerHostInfo) {
		os := detectOS(copied)
		oses = append(oses, os)
	}
	return oses
}

func imageServerInfos(containerHostInfo config.ServerInfo) (infos []config.ServerInfo) {
	imageNames := make([]string, 0, len(containerHostInfo.Images))
	for name := range containerHostInfo.Images {
		imageNames = append(imageNames, name)
	}
	sort.Strings(imageNames)

	for idx, name := range imageNames {
		image := containerHostInfo.Images[name]
		copied := containerHostInfo
		copied.ServerName = fmt.Sprintf("%d@%s", idx, containerHostInfo.ServerName)
		copied.Image = image
		copied.Type = ""
		infos = append(infos, copied)
	}
	return infos
}

